{
  "decision": "accept",
  "icd10_code": "E11.22",
  "code_display": "Type 2 DM with diabetic CKD",
  "guideline_citations": [
    {
      "url": "https://www.cms.gov/files/document/fy-2027-icd-10-cm-coding-guidelines.pdf",
      "quote": "The classification presumes a causal relationship between the two conditions linked by these terms in the Alphabetic Index or Tabular List. These conditions should be coded as related even in the absence of provider documentation explicitly linking them, unless the documentation clearly states the conditions are unrelated or when another guideline exists that specifically requires a documented linkage between two conditions (e.g., sepsis guideline for “acute organ dysfunction that is not clearly associated with the sepsis”).",
      "source": "official"
    }
  ],
  "rationale": "The chart contains multiple explicit statements supporting both type 2 diabetes mellitus and diabetic chronic kidney disease: 'Type 2 diabetes mellitus.', 'Chronic kidney disease stage 3.', 'Assessment: type 2 diabetes mellitus with hyperglycemia, currently active.', and 'Diabetic nephropathy is active.' No negation, family history, screening, hypothetical, or resolved language appears in the mention windows. The guideline excerpt confirms that a causal relationship is presumed for combination codes such as E11.22, and the documentation explicitly links the conditions ('Diabetic nephropathy is active'). Therefore, the combination code is fully supported.",
  "physician_query_needed": false
}
